import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Boss } from '../Entity/Boss';
import type { Turret } from '../Entity/Turret';
import type { TurretScheduleState } from '../Entity/TurretSchedule';

/**
 * 编排：决定当前哪个炮台有开火权，写到 turret.active。
 * 不碰瞄准、不碰开火。
 */
export class TurretScheduleSystem implements System {

    onTick(world: World, dt: number): void {
        for (const boss of world.query<Boss>('boss')) {
            if (!boss.alive || boss.hp <= 0) continue;
            this._tickSchedule(world, boss, dt);
        }
    }

    private _tickSchedule(world: World, boss: Boss, dt: number): void {
        const turrets = this._collectTurrets(world, boss);
        const schedule = boss.turretSchedule;

        // 无 schedule 或 volley：所有炮台 active
        if (!schedule || schedule.config.mode === 'volley') {
            for (const t of turrets) if (t) t.active = true;
            return;
        }

        // sequence 模式
        this._tickSequence(boss, schedule, turrets, dt);
    }

    private _collectTurrets(world: World, boss: Boss):  (Turret | null)[] {
        const result: (Turret | null)[] = [];
        for (const id of boss.turretIds) {
            if (id === 0) { result.push(null); continue; }
            result.push(this._findTurretById(world, boss, id));
        }
        return result;
    }

    private _findTurretById(world: World, boss: Boss, id: number): Turret | null {
        for (const t of world.query<Turret>('turret')) {
            if (t.id === id && t.ownerId === boss.id && t.alive && t.hp > 0) {
                return t;
            }
        }
        return null;
    }

    private _tickSequence(
        boss: Boss,
        schedule: TurretScheduleState,
        turrets:  (Turret | null)[],
        dt: number,
    ): void {
        // 先全部清零
        for (const t of turrets)  if (t)t.active = false;

        // 已结束
        if (schedule.activeIndex < 0) return;

        // 喘息中
        if (schedule.gapTimer > 0) {
            schedule.gapTimer -= dt;
            if (schedule.gapTimer <= 0) {
                schedule.gapTimer = 0;
                schedule.burstElapsed = 0;
            }
            return;
        }

        // 当前 active 的炮台
        const turret = turrets[schedule.activeIndex];
        if (!turret) {
            // 槽位死亡（或越界）：跳到下一个活槽位，本帧不开火
            this._advanceTurret(turrets, schedule);
            return;
        }
        turret.active = true;

        // 累积持续时间
        schedule.burstElapsed += dt;
        const burstDuration = schedule.config.burstDuration ?? 2;
        if (schedule.burstElapsed >= burstDuration) {
            this._advanceTurret(turrets, schedule);
        }
    }

    private _advanceTurret(turrets: (Turret | null)[], schedule: TurretScheduleState): void {
        const n = turrets.length;
        if (n === 0) {
            schedule.activeIndex = -1;
            return;
        }

        const loop = schedule.config.loop ?? true;
        let next = schedule.activeIndex;
        let guard = 0;

        do {
            next++;
            if (next >= n) {
                if (!loop) {
                    schedule.activeIndex = -1;
                    schedule.burstElapsed = 0;
                    schedule.gapTimer = 0;
                    return;
                }
                next = 0;
            }
            if (guard++ > n) {
                // 全部槽位都死了，loop 也没意义了
                schedule.activeIndex = -1;
                return;
            }
        } while (!turrets[next]);

        schedule.activeIndex = next;
        const t = turrets[next];
        if (t) t.cooldownTimer = 0;
        schedule.gapTimer = schedule.config.burstGap ?? 1;
        schedule.burstElapsed = 0;
    }
}